head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_seq = '';
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;
scwin.gUpDepCd = js_belngdepcd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.initPage();
        $c.cm.fn_com_isur(txb_isur_cd, txb_COM_NM);
        // fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        // var vTotalCnt = dts_Grid.NameString(1, "CNT");
        // alert("vTotalCnt=" + vTotalCnt);
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (colid === "DECLR_NM") {
            // 권한 추가 20240621
            if (dts_Grid.getCellData(row, "CHECK_YN") === "Y") {
                await scwin.readDecl(dts_Grid.getCellData(row, "DECL_SEQ"));
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        scwin.setKey(dts_Grid.getCellData(row, "DECL_SEQ"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        scwin.key_seq = '';
        await scwin.readDecl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Modify_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.btn_Modify_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30410.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: '불성실공시 신고포상현황', type: 8});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnCloseUp
 * @description grd Grid On Close Up 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnCloseUp = function(row, colid) {
    try {
        if (colid === "RWD_PNT_CONV_YN") {
            if (dts_Grid.getCellData(row, colid) === "Y" && dts_Grid.getCellData(row, "DECL_CORP_IMPOST_PNLT") !== "") {
                dts_Grid.setCellData(row, "DECLR_RWD_PNT", dts_Grid.getCellData(row, "DECL_CORP_IMPOST_PNLT"));
            } else {
                dts_Grid.setCellData(row, "DECLR_RWD_PNT", "미해당");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.grd_Grid_OnCloseUp" });
    }
};

/**
 * @method
 * @name grd_Grid_onexit
 * @description grd_Grid onexit 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} olddata olddata
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_onexit = async function(row, colid, olddata) {
    try {
        if ((colid === "DECL_CORP_IMPOST_PNLT" || colid === "DECLR_RWD_AMT" || colid === "DECLR_ANUL_RWD_AMT")) {
            await scwin.checkNum(row, colid, olddata);
        }
        if ((colid === "DECL_PROCS_END_DD" || colid === "DECL_CORP_NFAITH_ADVNOTI_DD" || colid === "DECL_CORP_NFAITH_DESIGN_DD" || colid === "DECLR_RWD_DD" || colid === "DECLR_ANUL_RWD_DD")) {
            await scwin.checkDate(row, colid, olddata);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.grd_Grid_onexit" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30410.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30410.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description rdo_MKT_ID onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // fn_SetCtrlByMktId();

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name initPage
 * @description 1. 날짜 기본 6개월.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    // 1. 날짜 기본 6개월.
    let ToDay = $c.ut.cGetToday2();
    edt_EDATE.setValue(ToDay);
    const vSDATE = $c.ut.calcMonth(ToDay, -3);
    edt_SDATE.setValue(vSDATE);
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (scwin.gLdMktTp !== '9') {
        panel_mkt.hide();
    }

    /**
    dts_DECLR_TP.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT"+
    						"&FOR=R&CD_ID=02571&CD_ENG_NM=DECLR_TP_CD" ;
    dts_DECLR_TP.Reset();
     **/
    /*
    <!--<column id="DEP_NM" width="100" name="담당팀" value="{DECODE(DEL_DEP_CD, 'YYYY', DEP_NM, DEL_DEP_NM)}" sort="true" edit="none" headcolor="#ffffff" headbgcolor="#598fd5"></column>
    					<column id="EMP_NM" width="100" name="담당자" sort="true" edit="none" headcolor="#ffffff" headbgcolor="#598fd5"></column>-->
     */
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 포상대상년도 항목의 콤보박스 값 설정(2011년 ~ 현재년도+1)
    let ToDay = new Date();
    let yyyy = parseInt(ToDay.getYear(), 10);
    yyyy = yyyy + 1;
    let str = "2011:2011년";
    for (let i = 2012; i <= yyyy; i++) {
        str += "," + i + ":" + i + "년";
    }
    str += ",-1:미해당";
    $c.cm.setColumnProp(grd_Grid, "RWD_OBJ_YY", 'data', str);
    // data="2011:2011년,2012:2012년,-1:미해당"

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.gDepCd === "UPTEAM" && js_dep_cd.substr(2, 4) === '00') {
        // 부서장 처리
        scwin.gUpDepCd = js_dep_cd;
    }
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&DECL_CORP_NFAITHDISCLS_TP_CD=" + cmb_DECL_CORP_NFAITHDISCLS_TP_CD.getValue(); // 불성실공시 유형분코드
    url += "&DECLR_TP_CD=" + cmb_DECLR_TP_CD.getValue();
    url += "&DECLR_NM=" + txb_DECLR_NM.getValue();
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&EMP_NO=" + cmb_EmpList.getValue(); // 담당자
    url += "&DEP_CD=" + cmb_TeamList.getValue(); // 팀(부서코드)
    url += "&UP_DEP_CD=" + scwin.gUpDepCd; // 상위부서코드
    url += "&SCREN_ID=" + "ULDSTF30410.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
