/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let gCnt = 0;
    for (let k = 1; k <= dts_Grid.getRowCount(); k++) {
        gStat = dts_Grid.getRowStatus(k);
        if (gStat === TB_JOB_UPDATE) {
            gCnt++;
        }
    }
    grd_Grid.Redraw = true;
    if (gCnt === 0) {
        await $c.win.alert("저장할 내용이 없습니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건] 저장하겠습니까?")) {
        let url = "/UnfaithfulDesignReport.do?method=procsNfaithDsclDecl&TRANSTR_EMP_NO=" + js_emp_no + "&SCREN_ID=" + "ULDSTF30410.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_save.Post();
    }
};

